-</script>
+const $=s=>document.querySelector(s), gameEl=$('#game'), scene=new THREE.Scene();
+scene.background=new THREE.Color(0x9d827d);scene.fog=new THREE.Fog(0x9d827d,28,92);
+const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);
+const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;gameEl.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xc8e2ff,0x44332f,2));const sun=new THREE.DirectionalLight(0xffd5a0,3.4);sun.position.set(-12,23,14);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-30;sun.shadow.camera.right=30;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-30;scene.add(sun);
+const mats={ground:new THREE.MeshStandardMaterial({color:0x77706a,roughness:.95}),stone:new THREE.MeshStandardMaterial({color:0xaaa19a,roughness:.8}),dark:new THREE.MeshStandardMaterial({color:0x343b4d,roughness:.78}),red:new THREE.MeshStandardMaterial({color:0x8e3738,roughness:.7}),wood:new THREE.MeshStandardMaterial({color:0x5b3931,roughness:.85}),leaf:new THREE.MeshStandardMaterial({color:0x536d62,roughness:.9}),gold:new THREE.MeshStandardMaterial({color:0xe9b657,metalness:.45,roughness:.4})};
+const floor=new THREE.Mesh(new THREE.CircleGeometry(30,64),mats.ground);floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);
+function box(parent,x,y,z,sx,sy,sz,mat){const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
+function cylinder(parent,x,y,z,r1,r2,h,mat,seg=10){let o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
+function buildWorld(){
+ // circular stone arena, radial seams and raised boundary stones
+ for(let i=0;i<32;i++){const a=i/32*Math.PI*2;const seam=box(scene,Math.sin(a)*11,.005,Math.cos(a)*11,.045,.02,22,new THREE.MeshStandardMaterial({color:0x625e5e,roughness:1}));seam.rotation.y=a;}
+ const outer=new THREE.Mesh(new THREE.TorusGeometry(14,.14,8,90),mats.gold);outer.rotation.x=Math.PI/2;outer.position.y=.03;scene.add(outer);
