+ // Hokage monument on the horizon
+ for(let i=0;i<4;i++){const g=new THREE.Group();scene.add(g);let x=-13+i*3.1;box(g,x,7,-24,2.3,3.6,.8,new THREE.MeshStandardMaterial({color:[0xc6a898,0xa0abb2,0xd4b474,0xbab5b4][i],roughness:.95}));const head=new THREE.Mesh(new THREE.SphereGeometry(1.35,12,10),new THREE.MeshStandardMaterial({color:[0xc6a898,0xa0abb2,0xd4b474,0xbab5b4][i]}));head.position.set(x,9.3,-24);g.add(head);box(g,x,10.2,-24,2.7,.45,.9,mats.stone);}
+ // torii at rear & lanterns
+ for(let side of [-1,1]){box(scene,side*7,3,-17,.5,6,.5,mats.red);box(scene,side*7,6,-17,1,1,.65,mats.red);}
+ box(scene,0,6.6,-17,15,.55,.8,mats.red);box(scene,0,5.9,-17,12,.28,.7,mats.gold);
+ for(let x of [-8,8]){cylinder(scene,x,1.4,-5,.18,.2,2.6,mats.wood);const lamp=new THREE.Mesh(new THREE.BoxGeometry(.8,.8,.8),new THREE.MeshStandardMaterial({color:0xffa653,emissive:0xff6b23,emissiveIntensity:1.6}));lamp.position.set(x,2.8,-5);scene.add(lamp);}
+ // stylized trees around edge
+ for(let i=0;i<11;i++){let a=i/11*Math.PI*2,x=Math.sin(a)*17,z=Math.cos(a)*17;cylinder(scene,x,2.1,z,.35,.55,4,mats.wood,7);for(let j=0;j<3;j++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(2.2-j*.25,1),mats.leaf);crown.position.set(x+(Math.random()-.5),3.7+j*1.3,z);crown.castShadow=true;scene.add(crown);}}
+}
