progress=JSON.parse(localStorage.getItem('shinobi-save')||'{"wins":0,"xp":0,"level":1,"streak":0}');
function material(hex,rough=.72,metal=0){return new THREE.MeshStandardMaterial({color:hex,roughness:rough,metalness:metal})}
function part(parent,geo,mat,pos,scale){const o=new THREE.Mesh(geo,mat);o.position.set(...pos);if(scale)o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function makeFighter(info,isEnemy=false,isNPC=false){
 const root=new THREE.Group(), rig=new THREE.Group();root.add(rig);scene.add(root);
 const cloth=material(info.color),accent=material(info.accent),skin=material(info.skin||0xe8b899),dark=material(0x20232b),metal=material(0xadb8c8,.35,.55),eye=material(0x171820,.35),hair=material(info.hair||info.color),band=material(0x3e4659,.42,.3);
 const torso=new THREE.Group();torso.position.y=1.28;rig.add(torso);
 part(torso,new THREE.CapsuleGeometry(.43,.58,4,8),cloth,[0,0,0],[1,.85,.82]);
 part(torso,new THREE.BoxGeometry(.78,.22,.85),accent,[0,.25,0],[1,1,1]);
 part(torso,new THREE.BoxGeometry(.13,.5,.88),dark,[0,-.2,0],[1,1,1]);
 const collar=part(torso,new THREE.ConeGeometry(.3,.45,4),accent,[0,.5,.02]);collar.rotation.z=Math.PI;
 // belt and pouch
 part(torso,new THREE.CylinderGeometry(.42,.42,.11,10),dark,[0,-.39,0],[1,1,.85]);part(torso,new THREE.BoxGeometry(.25,.23,.14),metal,[.18,-.4,.4]);
 const head=new THREE.Group();head.position.set(0,2.13,0);rig.add(head);
 part(head,new THREE.SphereGeometry(.38,16,12),skin,[0,0,0],[.85,1.04,.8]);
 part(head,new THREE.SphereGeometry(.4,12,8),hair,[0,.19,-.015],[1.04,.64,1]);
 // distinctive anime hair spikes
 for(let n=0;n<7;n++){const a=n/7*Math.PI*2;const spike=part(head,new THREE.ConeGeometry(.14,.43,5),hair,[Math.sin(a)*.28,.39,Math.cos(a)*.23]);spike.rotation.x=-.5;spike.rotation.z=Math.sin(a)*.35;}
 part(head,new THREE.BoxGeometry(.58,.13,.12),band,[0,.18,.29]);part(head,new THREE.BoxGeometry(.27,.105,.035),metal,[0,.18,.36]);
 for(let s of [-1,1]){part(head,new THREE.SphereGeometry(.045,8,6),eye,[s*.14,.015,.316]);part(head,new THREE.BoxGeometry(.16,.035,.025),dark,[s*.14,.09,.316]);}
 const limbs={};
 for(const side of [-1,1]){
  const arm=new THREE.Group();arm.position.set(side*.51,1.62,0);rig.add(arm);limbs[side<0?'la':'ra']=arm;
  part(arm,new THREE.CapsuleGeometry(.145,.43,4,7),cloth,[0,-.28,0],[1,1,1]);part(arm,new THREE.SphereGeometry(.17,10,8),accent,[0,-.57,.02]);part(arm,new THREE.BoxGeometry(.19,.16,.22),skin,[0,-.7,.03]);
  const leg=new THREE.Group();leg.position.set(side*.22,.83,0);rig.add(leg);limbs[side<0?'ll':'rl']=leg;
  part(leg,new THREE.CapsuleGeometry(.19,.47,4,7),cloth,[0,-.28,0],[1,1,1]);part(leg,new THREE.BoxGeometry(.28,.16,.46),dark,[0,-.62,.12]);
 }
 // back scarf/coat panel
 const cape=part(rig,new THREE.BoxGeometry(.58,.88,.12),accent,[0,1.27,-.47]);cape.rotation.x=-.1;
 // decorative shoulder pads and shinobi emblem
 for(const s of [-1,1])part(torso,new THREE.SphereGeometry(.2,8,6),accent,[s*.42,.23,-.02],[1,.8,1]);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x10111a,transparent:true,opacity:.32,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.018;root.add(shadow);
 root.position.set(isEnemy?2.8:-2.8,0,isNPC?Math.random()*1-1:0);root.rotation.y=isEnemy?Math.PI:0;
 return {root,rig,torso,head,limbs,info,enemy:isEnemy,npc:isNPC,hp:100,maxHp:100,chakra:50,sub:100,stun:0,attackCd:0,skillCd:0,projectileCd:0,dodge:0,guard:false,attackAnim:0,hitTargets:0,combo:0,comboTimer:0,aiTimer:.4+Math.random()*.4,walk:0,baseSpeed:5.2,jump:0,jumpV:0,awake:0,alive:true,brain:'idle',name:info.name};
}
function removeFighters(){for(const f of fighters)scene.remove(f.root);fighters=[];for(const n of npcList)scene.remove(n.root);npcList=[];projectiles.forEach(p=>scene.remove(p.mesh));projectiles=[];}
function spawnVillageNPCs(){removeFighters();const names=[['Rock Lee',8],['Konan',10],['Kisame',11],['Shisui',14]];npcList=names.map(([name,id],i)=>{const f=makeFighter(roster[id],i%2===0,true);f.root.position.set([-7,-2,3,7][i],0,[-3,-7,-5,-2][i]);f.root.rotation.y=.3;f.level=4+i*3;f.hp=80+i*7;f.challenge=true;return f;});}
function fireProjectile(owner,kind='kunai',target){const color=kind==='kunai'?0xd8e4ed:owner.info.accent;const mesh=new THREE.Mesh(kind==='kunai'?new THREE.OctahedronGeometry(.16,0):new THREE.IcosahedronGeometry(.35,1),material(color,.25,.5));mesh.position.copy(owner.root.position).add(new THREE.Vector3(0,1.45,0));scene.add(mesh);let dir=new THREE.Vector3();if(target)dir.subVectors(target.root.position,owner.root.position).setY(0).normalize();else dir.set(Math.sin(owner.root.rotation.y),0,Math.cos(owner.root.rotation.y));if(kind==='kunai')mesh.rotation.set(.6,.5,.7);projectiles.push({mesh,owner,dir,speed:kind==='kunai'?17:11,damage:kind==='kunai'?7:16,life:2,kind});}

