function showNotice(text){const n=$('#notice');n.textContent=text;n.classList.add('show');noticeTimer=2.15}
function showPanel(html){$('#panel').innerHTML=html;$('#menu').classList.remove('hidden')}
function closePanel(){ $('#menu').classList.add('hidden') }
function mainMenu(){mode='menu';showPanel(`<div class="eyebrow">NARUTO FAN EXPERIENCE · 3D ACTION</div><h1 class="title">ULTIMATE<br><span>SHINOBI</span></h1><p class="desc">A era dos deuses começou. Escolha seu caminho, domine o chakra e conquiste seu lugar entre as lendas shinobi.</p><div class="row"><div class="roundtag">NV. ${progress.level}</div><div class="roundtag">${progress.wins} VITÓRIAS</div><div class="roundtag">${progress.xp} XP</div></div><div class="menu-actions"><button class="main-btn" data-action="battle">BATALHA LIVRE <strong>01 →</strong></button><button class="main-btn" data-action="explore">EXPLORAR A VILA <strong>02 →</strong></button><button class="main-btn" data-action="roster">ELENCO & CONTROLES <strong>03 →</strong></button></div><div class="small-note">Inspirado no universo ninja. Personagens e mundo 3D construídos proceduralmente para este jogo.</div>`)}
function selectionMenu(){mode='select';let cards=roster.map((f,i)=>`<button class="fighter-card ${i===playerPick?'selected':''}" data-pick="${i}" data-side="player"><b>${f.name}</b><small>${f.title}</small><span class="sigil">${f.symbol}</span></button>`).join('');let foes=roster.map((f,i)=>`<button class="fighter-card ${i===enemyPick?'selected':''}" data-pick="${i}" data-side="enemy"><b>${f.name}</b><small>${f.style}</small><span class="sigil">${f.symbol}</span></button>`).join('');showPanel(`<div class="eyebrow">MODO BATALHA LIVRE</div><h2 class="title">ESCOLHA SEU <span>SHINOBI</span></h2><div class="field-label">Jogador · ${roster[playerPick].name}</div><div class="roster">${cards}</div><div class="field-label">Adversário · ${roster[enemyPick].name}</div><div class="roster">${foes}</div><div class="row"><div><div class="field-label">Cenário</div><select class="select" id="stageSelect">${stages.map((s,i)=>`<option value="${i}" ${i===stagePick?'selected':''}>${s}</option>`).join('')}</select></div><div><div class="field-label">Dificuldade</div><select class="select" id="diffSelect">${difficulties.map((s,i)=>`<option value="${i}" ${i===difficultyPick?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="modal-footer"><button class="back" data-action="home">← VOLTAR</button><button class="primary" data-action="startfight">INICIAR LUTA</button></div>`)}
function rosterMenu(){mode='info';let cards=roster.map(f=>`<div class="fighter-card"><b>${f.name}</b><small>${f.title}<br>${f.skill}</small><span class="sigil">${f.symbol}</span></div>`).join('');showPanel(`<div class="eyebrow">18 SHINOBI · COMBATE REAL</div><h2 class="title">ELENCO & <span>COMANDOS</span></h2><div class="roster">${cards}</div><p class="desc"><b>J</b> combo físico · <b>K</b> kunai · <b>L</b> ninjutsu (chakra) · <b>O</b> técnica final · <b>I</b> defesa · <b>U</b> substituição · <b>Shift</b> esquiva · <b>R</b> despertar · <b>Espaço</b> pulo.<br><br>No modo exploração, use <b>WASD</b> e pressione <b>E</b> perto de um rival para desafiá-lo.</p><div class="modal-footer"><button class="back" data-action="home">← VOLTAR</button><button class="primary" data-action="battle">BATALHA</button></div>`)}
function startBattle(pickA=playerPick,pickB=enemyPick,aiLevel=difficultyPick,quick=false){removeFighters();playerPick=pickA;enemyPick=pickB;difficultyPick=aiLevel;const p=makeFighter(roster[pickA]),e=makeFighter(roster[pickB],true);fighters=[p,e];worldMode='battle';mode='fight';roundOver=false;fightTime=99;elapsed=0;combatRound++;p.root.position.set(-2.8,0,0);e.root.position.set(2.8,0,0);p.hp=e.hp=100;p.chakra=e.chakra=58;p.sub=e.sub=100;$('#modeTag').textContent=stages[stagePick].toUpperCase();$('#pName').textContent=p.info.name;$('#eName').textContent=e.info.name;$('#pLevel').textContent=`NV. ${progress.level}`;$('#eLevel').textContent=difficulties[aiLevel].toUpperCase();$('#roundText').textContent=`ROUND ${combatRound}`;$('#hud').classList.add('active');$('#hint').textContent='WASD mover · J atacar · K kunai · L jutsu · I defender · U substituição';$('#combo').classList.remove('show');closePanel();showNotice('LUTEM!');}
function beginExplore(){removeFighters();const p=makeFighter(roster[playerPick]);p.root.position.set(0,0,5);player=p;spawnVillageNPCs();worldMode='village';mode='explore';$('#hud').classList.remove('active');$('#modeTag').textContent='VILA DA FOLHA';$('#hint').textContent='WASD mover · E conversar / desafiar · Shift correr';closePanel();showNotice('Encontre um ninja e pressione E para desafiá-lo.');}
let player=makeFighter(roster[0]);spawnVillageNPCs();
$('#panel').addEventListener('click',e=>{const pick=e.target.closest('[data-pick]');if(pick){const i=+pick.dataset.pick;if(pick.dataset.side==='player')playerPick=i;else enemyPick=i;selectionMenu();return;}const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'home':mainMenu();break;case'battle':selectionMenu();break;case'roster':rosterMenu();break;case'explore':beginExplore();break;case'startfight':stagePick=+$('#stageSelect').value;difficultyPick=+$('#diffSelect').value;startBattle();break;case'return':mainMenu();break;case'retry':startBattle(playerPick,enemyPick,difficultyPick);break;case'next':startBattle(playerPick,(enemyPick+1)%roster.length,Math.min(5,difficultyPick+1));break;}});
mainMenu();
</script>
</body></html>

