const stageDecor=[];function setStage(idx){stageDecor.forEach(o=>scene.remove(o));stageDecor.length=0;const themes=[{bg:0x9d827d,fog:0x9d827d,floor:0x77706a},{bg:0x9babb0,fog:0x9babb0,floor:0x80848a},{bg:0x65746b,fog:0x65746b,floor:0x646a5d},{bg:0xe9a978,fog:0xe9a978,floor:0xb18a68}][idx];scene.background.setHex(themes.bg);scene.fog.color.setHex(themes.fog);mats.ground.color.setHex(themes.floor);if(idx===0){for(let side of [-1,1]){const rock=part(scene,new THREE.IcosahedronGeometry(3,1),material(0x68706e),[side*8,1.3,-17],[1.3,1.9,1]);stageDecor.push(rock);}}if(idx===2){for(let i=0;i<8;i++){const tree=part(scene,new THREE.ConeGeometry(1.7,6,7),material(i%2?0x345348:0x405e4d),[(Math.random()-.5)*25,3,-15-Math.random()*8]);stageDecor.push(tree);}}if(idx===3){for(let i=0;i<9;i++){const rock=part(scene,new THREE.IcosahedronGeometry(1.5+Math.random(),1),material(0xb5906d),[(Math.random()-.5)*25,.8,-12-Math.random()*9],[1,1.3,1]);stageDecor.push(rock);}}}
function popFx(pos,color=0xffc15d,amount=9){for(let i=0;i<amount;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.055+Math.random()*.08,6,5),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);particles.push({mesh:m,v:new THREE.Vector3((Math.random()-.5)*5,Math.random()*5,(Math.random()-.5)*5),life:.42+Math.random()*.4});}}
let pendingHits=[];
function applyHit(attacker,target,damage,kind='strike'){if(!target.alive||target.dodge>0)return false;const dir=new THREE.Vector3().subVectors(target.root.position,attacker.root.position).setY(0).normalize();if(target.guard&&kind!=='ultimate'){damage*=.22;target.stun=Math.max(target.stun,.12);}else{target.stun=Math.max(target.stun,kind==='ultimate'?.9:.34);target.root.position.addScaledVector(dir,kind==='ultimate'?1.5:.6);}target.hp=Math.max(0,target.hp-damage);target.comboTimer=2.2;if(!attacker.enemy){attacker.combo++;$('#combo').innerHTML=`${attacker.combo} <small>ACERTOS</small>`;$('#combo').classList.add('show');}target.sub=Math.min(100,target.sub+(kind==='ultimate'?15:7));popFx(target.root.position.clone().add(new THREE.Vector3(0,1.3,0)),kind==='skill'?attacker.info.accent:0xffd36a,kind==='ultimate'?22:10);cameraShake=Math.max(cameraShake,kind==='ultimate'?.55:.15);if(target.hp<=0){target.alive=false;endBattle(attacker===fighters[0]);}return true;}
function attack(f){if(f.stun>0||f.attackCd>0||!f.alive)return;f.attackCd=f.awake?.24:.34;f.attackAnim=.38;f.hitDone=false;f.brain='attack';}
function castSkill(f,target){if(f.chakra<24||f.skillCd>0||f.stun>0)return;f.chakra-=24;f.skillCd=2.1;f.attackAnim=.3;f.brain='skill';fireProjectile(f,'skill',target);showNotice(`${f.info.skill.toUpperCase()}!`);}
function ultimate(f,target){if(f.chakra<48||f.skillCd>0||f.stun>0)return;f.chakra-=48;f.skillCd=5.5;f.brain='ultimate';f.attackAnim=.8;cameraShake=.8;showNotice(`TÉCNICA FINAL: ${f.info.skill.toUpperCase()}`);pendingHits.push({time:.46,attacker:f,target,damage:34,kind:'ultimate'});}
function doAction(f,target){if(!f||!f.alive||roundOver)return;if(keys.j&&f.attackCd<=0)attack(f);if(pressed.k){if(f.projectileCd<=0){fireProjectile(f,'kunai',target);f.projectileCd=.7;}}if(pressed.l)castSkill(f,target);if(pressed.o)ultimate(f,target);if(pressed.u&&f.sub>=28){f.sub-=28;f.dodge=.58;f.root.visible=false;setTimeout(()=>{if(f.root)f.root.visible=true},180);popFx(f.root.position.clone().add(new THREE.Vector3(0,1,0)),0xc9a3ff,12);showNotice('SUBSTITUIÇÃO!');}if(pressed.r&&f.chakra>=35&&f.awake<=0){f.chakra-=35;f.awake=10;f.baseSpeed=7.1;showNotice('DESPERTAR — CHAKRA LIBERADO!');}}
function enemyAI(f,target,dt){if(!target?.alive||f.stun>0)return;const lv=difficultyPick,diff=Math.max(.15,[.42,.58,.78,1,1.18,1.35][lv]),d=f.root.position.distanceTo(target.root.position);f.aiTimer-=dt;f.guard=false;if(f.aiTimer>0)return;f.aiTimer=(.25+Math.random()*.5)/diff;
 if(lv>=2&&target.attackAnim>.16&&d<3.6&&Math.random()<(.25+lv*.095)){if(lv>=4&&Math.random()<.35){f.dodge=.45;f.root.position.x+=(f.root.position.x-target.root.position.x>0?1:-1)*1.5;}else f.guard=true;return;}
 if(lv>=3&&d<3.3&&f.chakra>=24&&Math.random()<.15+lv*.035){castSkill(f,target);return;}
 if(lv>=5&&f.chakra>=48&&d<7&&Math.random()<.12){ultimate(f,target);return;}
 if(d>2.65){const dir=new THREE.Vector3().subVectors(target.root.position,f.root.position).setY(0).normalize();f.root.position.addScaledVector(dir,Math.min(d-2.25,f.baseSpeed*diff*dt));f.walk+=dt*8;}else if(f.attackCd<=0&&Math.random()<diff){attack(f);}else if(lv>=2&&d>4&&Math.random()<.28){fireProjectile(f,'kunai',target);f.projectileCd=.8;}
}
function endBattle(won){if(roundOver)return;roundOver=true;const earned=won?180+30*difficultyPick:50;progress.xp+=earned;if(won){progress.wins++;progress.streak++;}else progress.streak=0;progress.level=Math.floor(progress.xp/600)+1;localStorage.setItem('shinobi-save',JSON.stringify(progress));setTimeout(()=>{const label=won?'VITÓRIA':'DERROTA';$('#hud').classList.remove('active');$('#hint').textContent='';showPanel(`<div class="eyebrow">ROUND ${combatRound} · ${stages[stagePick]}</div><div class="result-mark">${label}</div><h2 class="title" style="text-align:center">${won?'HONRA AO SHINOBI':'TENTE NOVAMENTE'}</h2><p class="desc" style="text-align:center">${won?'Adversário derrotado.':'A batalha ainda não acabou.'} Você recebeu <b style="color:var(--gold)">${earned} XP</b>. Nível ${progress.level} · ${progress.wins} vitórias.</p><div class="menu-actions"><button class="main-btn" data-action="retry">REVANCHE <strong>↻</strong></button><button class="main-btn" data-action="next">PRÓXIMO DESAFIO <strong>→</strong></button><button class="main-btn" data-action="home">VOLTAR AO MENU <strong>⌂</strong></button></div>`);mode='result';},1000);}

